package com.tracker.controller;
import com.tracker.entity.*; import com.tracker.exception.ApiException; import com.tracker.repository.*; import com.tracker.service.AccessService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") @com.tracker.config.StudentOnly public class ResourceController { final SkillRepository skills; final CourseRepository courses; final CertificationRepository certs; final AccessService access; public ResourceController(SkillRepository s,CourseRepository c,CertificationRepository x,AccessService a){skills=s;courses=c;certs=x;access=a;} 
 @GetMapping("/skills/user/{id}") List<Skill> skillList(@PathVariable Long id,Authentication a){access.own(id,a);return skills.findByUserId(id);} @PostMapping("/skills") Skill skillAdd(@Valid @RequestBody Skill x,Authentication a){x.setId(null);x.setUser(access.current(a));return skills.save(x);} @PutMapping("/skills/{id}") Skill skillPut(@PathVariable Long id,@Valid @RequestBody Skill x,Authentication a){var old=skills.findById(id).orElseThrow(()->new ApiException("Skill not found",HttpStatus.NOT_FOUND));access.own(old.getUser().getId(),a);x.setId(id);x.setUser(old.getUser());return skills.save(x);} @DeleteMapping("/skills/{id}") void skillDelete(@PathVariable Long id,Authentication a){var x=skills.findById(id).orElseThrow(()->new ApiException("Skill not found",HttpStatus.NOT_FOUND));access.own(x.getUser().getId(),a);skills.delete(x);}
 @GetMapping("/courses/user/{id}") List<Course> courseList(@PathVariable Long id,Authentication a){access.own(id,a);return courses.findByUserId(id);} @PostMapping("/courses") Course courseAdd(@Valid @RequestBody Course x,Authentication a){x.setId(null);x.setUser(access.current(a));return courses.save(x);} @PutMapping("/courses/{id}") Course coursePut(@PathVariable Long id,@Valid @RequestBody Course x,Authentication a){var old=courses.findById(id).orElseThrow(()->new ApiException("Course not found",HttpStatus.NOT_FOUND));access.own(old.getUser().getId(),a);x.setId(id);x.setUser(old.getUser());return courses.save(x);} @DeleteMapping("/courses/{id}") void courseDelete(@PathVariable Long id,Authentication a){var x=courses.findById(id).orElseThrow(()->new ApiException("Course not found",HttpStatus.NOT_FOUND));access.own(x.getUser().getId(),a);courses.delete(x);}
 @GetMapping("/certifications/user/{id}") List<Certification> certList(@PathVariable Long id,Authentication a){access.own(id,a);return certs.findByUserId(id);} @GetMapping("/certifications/{id}") Certification cert(@PathVariable Long id,Authentication a){var x=certs.findById(id).orElseThrow(()->new ApiException("Certification not found",HttpStatus.NOT_FOUND));access.own(x.getUser().getId(),a);return x;} @PostMapping("/certifications") Certification certAdd(@Valid @RequestBody Certification x,Authentication a){x.setId(null);x.setStatus(CertStatus.PENDING);x.setUser(access.current(a));return certs.save(x);} @PutMapping("/certifications/{id}") Certification certPut(@PathVariable Long id,@Valid @RequestBody Certification x,Authentication a){var old=certs.findById(id).orElseThrow(()->new ApiException("Certification not found",HttpStatus.NOT_FOUND));access.own(old.getUser().getId(),a);x.setId(id);x.setUser(old.getUser());x.setStatus(old.getStatus());return certs.save(x);} @DeleteMapping("/certifications/{id}") void certDelete(@PathVariable Long id,Authentication a){var x=certs.findById(id).orElseThrow(()->new ApiException("Certification not found",HttpStatus.NOT_FOUND));access.own(x.getUser().getId(),a);certs.delete(x);}
 @GetMapping("/dashboard") Map<String,Object> dashboard(Authentication a){var u=access.current(a);return Map.of("skills",skills.countByUserId(u.getId()),"courses",courses.countByUserId(u.getId()),"certifications",certs.countByUserId(u.getId()),"approved",certs.countByUserIdAndStatus(u.getId(),CertStatus.APPROVED),"pending",certs.countByUserIdAndStatus(u.getId(),CertStatus.PENDING),"rejected",certs.countByUserIdAndStatus(u.getId(),CertStatus.REJECTED));}
}
